+void
+dfw_error_init(df_error_t *err) {
+	err->code = 0;
+	err->msg = NULL;
+	err->loc.col_start = -1;
+	err->loc.col_len = 0;
+}
+
+void
+dfw_error_clear(df_error_t *err) {
+	g_free(err->msg);
+	dfw_error_init(err);
+}
+
+void
+dfw_error_set_msg(df_error_t **errpp, const char *fmt, ...)
+{
+	if (errpp == NULL) {
+		return;
+	}
+	va_list ap;
+
+	df_error_t *errp = g_new(df_error_t, 1);
+	errp->code = DF_ERROR_GENERIC;
+	va_start(ap, fmt);
+	errp->msg = ws_strdup_vprintf(fmt, ap);
+	va_end(ap);
+	errp->loc.col_start = -1;
+	errp->loc.col_len = 0;
+	*errpp = errp;
+}
+
+void
+dfw_error_take(df_error_t **errpp, df_error_t *src)
+{
+	if (errpp == NULL) {
+		g_free(src->msg);
+		dfw_error_init(src);
+		return;
+	}
+	df_error_t *errp = g_new(df_error_t, 1);
+	errp->code = src->code;
+	errp->msg = src->msg;
+	errp->loc = src->loc;
+	*errpp = errp;
+	dfw_error_init(src);
+}
+
+void
+dfilter_error_free(df_error_t *errp)
+{
+	if (errp == NULL)
+		return;
+	g_free(errp->msg);
+	g_free(errp);
+}
